const raw = $input.first().json;
const partId = String(raw.part_id || '').trim();
const qty = Number(raw.shortage_quantity);
const requiredBy = String(raw.required_by || '').trim().slice(0,10);
if (!/^P\d{3}$/.test(partId)) throw new Error('part_id must look like P084');
if (!Number.isSafeInteger(qty) || qty <= 0) throw new Error('shortage_quantity must be a positive integer');
if (!/^\d{4}-\d{2}-\d{2}$/.test(requiredBy) || Number.isNaN(Date.parse(requiredBy + 'T00:00:00Z'))) throw new Error('required_by must be YYYY-MM-DD');
return [{json:{incident_id: String(raw.incident_id || 'unspecified'), part_id:partId, shortage_quantity:qty, required_by:requiredBy, production_at_risk: raw.production_at_risk === true}}];

const inventory = $input.first().json;
const part = inventory.part;

// Check the inventory response
if (!part || !part.part_id) {
  throw new Error("Part information missing");
}

// Get data from Agent 3
const input = $("Validate Input").first().json;

const shortageQty = Number(input.shortage_quantity);
const minOrderQty = Number(part.min_order_qty || 1);

// Calculate order quantity
const orderQty = Math.max(shortageQty, minOrderQty);

// Find all qualified suppliers
const suppliers = [
  part.preferred_supplier,
  ...String(part.qualified_alternates || "")
    .split(",")
    .map(s => s.trim())
].filter(s => s && s !== "nan");

// Remove duplicate suppliers
const uniqueSuppliers = [...new Set(suppliers)];

if (uniqueSuppliers.length === 0) {
  throw new Error("No qualified suppliers found");
}

// Generate sea and air quotes for each supplier
const candidates = [];

for (const supplierId of uniqueSuppliers) {
  for (const mode of ["sea", "air"]) {
    candidates.push({
      json: {
        incident_id: input.incident_id,
        part_id: part.part_id,
        supplier_id: supplierId,
        qty: orderQty,
        mode: mode,
        shortage_quantity: shortageQty,
        min_order_qty: minOrderQty,
        quantity_reason:
          orderQty > shortageQty
            ? "Minimum order quantity applied"
            : "Actual shortage quantity"
      }
    });
  }
}

return candidates;

const input = $('Validate Input').first().json;
const quotes = $input.all().map(item => item.json);
const requiredMs = Date.parse(input.required_by + 'T00:00:00Z');
const assessed = quotes.map(q => {
  const arrivalMs = Date.parse(String(q.earliest_arrival).slice(0,10) + 'T00:00:00Z');
  const valid = Boolean(q.quote_id && q.supplier_id && q.part_id === input.part_id && Number.isFinite(arrivalMs) && Number.isFinite(Number(q.total_aed)));
  return {...q, valid, arrives_on_time: valid && arrivalMs <= requiredMs, days_late: valid ? Math.max(0, Math.round((arrivalMs-requiredMs)/86400000)) : null};
}).filter(q => q.valid);
if (!assessed.length) throw new Error('No valid quotes returned');
const timely = assessed.filter(q => q.arrives_on_time).sort((a,b) => Number(a.total_aed)-Number(b.total_aed) || String(a.earliest_arrival).localeCompare(String(b.earliest_arrival)));
const late = assessed.filter(q => !q.arrives_on_time).sort((a,b) => String(a.earliest_arrival).localeCompare(String(b.earliest_arrival)) || Number(a.total_aed)-Number(b.total_aed));
const selected = timely[0] || late[0];
const ready = timely.length > 0;
return [{json:{
  incident_id:input.incident_id,
  part_id:input.part_id,
  shortage_quantity:input.shortage_quantity,
  ordered_quantity:selected.qty,
  minimum_order_quantity:
    Number($("Get Qualified Suppliers").first().json.part.min_order_qty || 1),

  quantity_reason:
    Number(selected.qty) > Number(input.shortage_quantity)
      ? "Minimum order quantity applied"
      : "Actual shortage quantity",
  required_by:input.required_by,
  status:ready ? 'ready_for_procurement' : 'escalate_no_on_time_quote',
  auto_procurement_allowed:ready,
  selected_quote_id:selected.quote_id,
  selected_supplier_id:selected.supplier_id,
  selected_mode:selected.mode,
  estimated_total_aed:selected.total_aed,
  earliest_arrival:selected.earliest_arrival,
  arrives_on_time:selected.arrives_on_time,
  justification:ready
    ? `Qualified ${selected.supplier_id}, ${selected.mode} shipping, quote ${selected.quote_id}; cost AED ${selected.total_aed}, arrival ${selected.earliest_arrival} by required date ${input.required_by}. Quantity ${selected.qty} includes supplier minimum if applicable.`
    : `No quoted supplier can meet ${input.required_by}. Earliest available option: ${selected.supplier_id} ${selected.mode}, arriving ${selected.earliest_arrival}; requires escalation and production replanning before ordering.`,
  comparison:assessed.sort((a,b)=>Number(b.arrives_on_time)-Number(a.arrives_on_time) || Number(a.days_late)-Number(b.days_late) || Number(a.total_aed)-Number(b.total_aed))
}}];
